-- Hail swaths for the storm map.
-- One storm, one track, and one polygon per size band. Weather rows are shared.
-- Job counts inside hail_at_point stay on the caller's company.

create schema if not exists extensions;
create extension if not exists postgis with schema extensions;

create table if not exists public.hail_storms (
  id uuid primary key default gen_random_uuid(),
  storm_date date not null,
  started_at timestamptz not null,
  ended_at timestamptz not null,
  radar_site text not null default '',
  storm_max_in numeric(4, 2) not null,
  source text not null default 'mesh',
  track extensions.geometry(LineString, 4326) not null
);

create table if not exists public.hail_swath_bands (
  id uuid primary key default gen_random_uuid(),
  storm_id uuid not null references public.hail_storms (id) on delete cascade,
  band_size_in numeric(4, 2) not null,
  geom extensions.geometry(MultiPolygon, 4326) not null,
  unique (storm_id, band_size_in)
);

create table if not exists public.hail_storm_reports (
  id uuid primary key default gen_random_uuid(),
  storm_id uuid not null references public.hail_storms (id) on delete cascade,
  size_in numeric(4, 2) not null,
  place text not null default '',
  reported_at timestamptz not null,
  lat double precision not null,
  lng double precision not null
);

create index if not exists hail_storms_date_idx on public.hail_storms (storm_date desc);
create index if not exists hail_storms_track_idx on public.hail_storms using gist (track);
create index if not exists hail_swath_bands_geom_idx on public.hail_swath_bands using gist (geom);
create index if not exists hail_swath_bands_storm_idx on public.hail_swath_bands (storm_id);
create index if not exists hail_storm_reports_storm_idx on public.hail_storm_reports (storm_id);

alter table public.hail_storms enable row level security;
alter table public.hail_swath_bands enable row level security;
alter table public.hail_storm_reports enable row level security;

drop policy if exists "read hail storms" on public.hail_storms;
create policy "read hail storms" on public.hail_storms
  for select to authenticated
  using (true);

drop policy if exists "read hail swaths" on public.hail_swath_bands;
create policy "read hail swaths" on public.hail_swath_bands
  for select to authenticated
  using (true);

drop policy if exists "read hail reports" on public.hail_storm_reports;
create policy "read hail reports" on public.hail_storm_reports
  for select to authenticated
  using (true);

revoke all on public.hail_storms from public, anon;
revoke all on public.hail_swath_bands from public, anon;
revoke all on public.hail_storm_reports from public, anon;
grant select on public.hail_storms to authenticated;
grant select on public.hail_swath_bands to authenticated;
grant select on public.hail_storm_reports to authenticated;

-- hail_at_point(p_lat double precision, p_lng double precision, p_since_days integer default 90)
-- One row per storm whose swath contains the point:
--   max band at the point, distance to the track, passage time interpolated
--   along the track, nearest NWS LSR, and this company's jobs inside the
--   outermost band.
create or replace function public.hail_at_point(
  p_lat double precision,
  p_lng double precision,
  p_since_days integer default 90
)
returns table (
  storm_id uuid,
  storm_date date,
  started_at timestamptz,
  ended_at timestamptz,
  radar_site text,
  storm_max_in double precision,
  max_band_in double precision,
  distance_to_core_mi double precision,
  passed_over_start timestamptz,
  passed_over_end timestamptz,
  estimated_passage_at timestamptz,
  lsr_size_in double precision,
  lsr_place text,
  lsr_reported_at timestamptz,
  jobs_in_swath integer
)
language sql
stable
security invoker
set search_path = public, extensions
as $$
  with point as (
    select ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326) as geom
  ),
  hits as (
    select
      s.id,
      s.storm_date,
      s.started_at,
      s.ended_at,
      s.radar_site,
      s.storm_max_in::double precision as storm_max_in,
      s.track,
      max(b.band_size_in)::double precision as max_band_in
    from public.hail_storms s
    join public.hail_swath_bands b on b.storm_id = s.id
    cross join point p
    where s.storm_date >= (timezone('America/Chicago', now()))::date - least(greatest(coalesce(p_since_days, 90), 1), 3650)
      and ST_Intersects(b.geom, p.geom)
    group by s.id
  )
  select
    h.id as storm_id,
    h.storm_date,
    h.started_at,
    h.ended_at,
    h.radar_site,
    h.storm_max_in,
    h.max_band_in,
    ST_Distance(h.track::geography, p.geom::geography) / 1609.344 as distance_to_core_mi,
    h.started_at
      + ((h.ended_at - h.started_at) * ST_LineLocatePoint(h.track, p.geom))
      - interval '4.5 minutes' as passed_over_start,
    h.started_at
      + ((h.ended_at - h.started_at) * ST_LineLocatePoint(h.track, p.geom))
      + interval '4.5 minutes' as passed_over_end,
    h.started_at
      + ((h.ended_at - h.started_at) * ST_LineLocatePoint(h.track, p.geom)) as estimated_passage_at,
    lsr.size_in::double precision as lsr_size_in,
    lsr.place as lsr_place,
    lsr.reported_at as lsr_reported_at,
    (
      select count(*)::integer
      from public.jobs j
      join public.hail_swath_bands outer_band
        on outer_band.storm_id = h.id
       and outer_band.band_size_in = (
         select min(band_size_in) from public.hail_swath_bands where storm_id = h.id
       )
      where j.company_id = public.current_company_id()
        and j.deleted_at is null
        and j.lat is not null
        and j.lng is not null
        and ST_Intersects(outer_band.geom, ST_SetSRID(ST_MakePoint(j.lng, j.lat), 4326))
    ) as jobs_in_swath
  from hits h
  cross join point p
  left join lateral (
    select r.size_in, r.place, r.reported_at
    from public.hail_storm_reports r
    where r.storm_id = h.id
    order by ST_Distance(
      ST_SetSRID(ST_MakePoint(r.lng, r.lat), 4326)::geography,
      p.geom::geography
    )
    limit 1
  ) lsr on true;
$$;

revoke all on function public.hail_at_point(double precision, double precision, integer) from public, anon;
grant execute on function public.hail_at_point(double precision, double precision, integer) to authenticated;

comment on table public.hail_storms is
  'Shared hail storms. Not tenant data. Job counts in hail_at_point use current_company_id().';
comment on function public.hail_at_point(double precision, double precision, integer) is
  'Storms whose swath contains a point, plus this company''s jobs inside the outer band.';

